{
  "id": "vuln-nocodb-079e3abe",
  "message": "The use of Papaparse.unparse without the 'escapeFormulae' option set to true can lead to CSV injection vulnerabilities. This allows attackers to inject malicious formulas into CSV files, which can be executed when the file is opened in spreadsheet software. To fix this, ensure that 'escapeFormulae: true' is included in the options object passed to Papaparse.unparse.",
  "severity": "ERROR",
  "languages": ["typescript"],
  "metadata": {
    "category": "security",
    "cwe": "CWE-1236",
    "owasp": "A1:2017-Injection"
  },
  "pattern": "Papaparse.unparse($OBJ)",
  "pattern_not": [
    "Papaparse.unparse($OBJ, { escapeFormulae: true, ... })"
  ]
}

